source.bookSourceComment:
try{
s=result.match(/"[^"]*[{}]{2,}[^"]+"/g);
for(i in s){
 x=s[i].match(/"([^"]*[{}]{2,})([^"]+)"/);
xx=java.aesBase64DecodeToString(x[2],"OW84U8Eerdb99rtsTXWSILDO","DESede/CBC/PKCS5Padding","SK8bncVu");
 result=result.replace(x[1]+x[2],xx)
	}
}catch(e){""}
result

